CREATE TABLE "agent_cap_pauses" (
	"agent_id" text PRIMARY KEY NOT NULL,
	"floor_id" text NOT NULL,
	"issue" integer,
	"period" text NOT NULL,
	"level" text NOT NULL,
	"cap" bigint NOT NULL,
	"used" bigint NOT NULL,
	"notice_id" text,
	"paused_at" timestamp with time zone NOT NULL,
	"resume_at" timestamp with time zone,
	CONSTRAINT "agent_cap_pauses_period" CHECK ("agent_cap_pauses"."period" IN ('daily', 'monthly')),
	CONSTRAINT "agent_cap_pauses_level" CHECK ("agent_cap_pauses"."level" IN ('office', 'floor', 'agent', 'issue')),
	CONSTRAINT "agent_cap_pauses_issue" CHECK ("agent_cap_pauses"."issue" IS NULL OR "agent_cap_pauses"."issue" > 0)
);

CREATE TABLE "agents" (
	"id" text PRIMARY KEY NOT NULL,
	"floor_id" text NOT NULL,
	"name" text NOT NULL,
	"role" text NOT NULL,
	"role_id" text GENERATED ALWAYS AS (CASE WHEN removed_at IS NULL THEN NULLIF(role, 'manager') END) STORED,
	"ai_provider" text NOT NULL,
	"model_override" text,
	"effort" text,
	"extra_instructions" text DEFAULT '' NOT NULL,
	"enabled" boolean DEFAULT true NOT NULL,
	"avatar" jsonb NOT NULL,
	"daily_token_cap" bigint,
	"monthly_token_cap" bigint,
	"fresh_start_threshold" integer,
	"created_at" timestamp with time zone NOT NULL,
	"leaving_at" timestamp with time zone,
	"removed_at" timestamp with time zone,
	"contractor_kind" text,
	"contractor_batch_id" bigint,
	CONSTRAINT "agents_contractor_kind" CHECK ("agents"."contractor_kind" IS NULL OR "agents"."contractor_kind" IN ('work', 'research')),
	CONSTRAINT "agents_contractor_batch" CHECK ("agents"."contractor_batch_id" IS NULL OR "agents"."contractor_kind" = 'work'),
	CONSTRAINT "agents_token_caps" CHECK (("agents"."daily_token_cap" IS NULL OR "agents"."daily_token_cap" > 0) AND ("agents"."monthly_token_cap" IS NULL OR "agents"."monthly_token_cap" > 0)),
	CONSTRAINT "agents_fresh_start_threshold" CHECK ("agents"."fresh_start_threshold" IS NULL OR "agents"."fresh_start_threshold" BETWEEN 10 AND 100)
);

CREATE TABLE "ai_account_usage" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "ai_account_usage_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"ai_account_id" text NOT NULL,
	"window" text NOT NULL,
	"utilization" double precision NOT NULL,
	"resets_at" timestamp with time zone NOT NULL,
	"observed_at" timestamp with time zone NOT NULL,
	CONSTRAINT "ai_account_usage_window" CHECK ("ai_account_usage"."window" IN ('five_hour', 'weekly')),
	CONSTRAINT "ai_account_usage_utilization" CHECK ("ai_account_usage"."utilization" >= 0)
);

CREATE TABLE "ai_accounts" (
	"id" text PRIMARY KEY NOT NULL,
	"name" text NOT NULL,
	"account_type" text NOT NULL,
	"ai_provider" text NOT NULL,
	"credential" text NOT NULL,
	"endpoint_url" text,
	"region" text,
	"project_id" text,
	"priority" integer NOT NULL,
	"paused" boolean DEFAULT false NOT NULL,
	"refresh_token" text,
	"token_expires_at" timestamp with time zone,
	"reauthentication_needed" boolean DEFAULT false NOT NULL,
	"limit_reason" text,
	"limited_until" timestamp with time zone,
	"five_hour_utilization" double precision,
	"five_hour_resets_at" timestamp with time zone,
	"weekly_utilization" double precision,
	"weekly_resets_at" timestamp with time zone,
	"five_hour_pause_threshold" integer,
	"weekly_pause_threshold" integer,
	"forced_model" text,
	"extra_usage" boolean DEFAULT false NOT NULL,
	"rate_limits" jsonb,
	"balance" jsonb,
	"created_at" timestamp with time zone NOT NULL,
	"updated_at" timestamp with time zone NOT NULL,
	CONSTRAINT "ai_accounts_name_unique" UNIQUE("name"),
	CONSTRAINT "ai_accounts_limit_reason" CHECK ("ai_accounts"."limit_reason" IS NULL OR "ai_accounts"."limit_reason" IN ('rate_limited', 'overloaded', 'circuit_open', 'extra_usage')),
	CONSTRAINT "ai_accounts_limit" CHECK (("ai_accounts"."limit_reason" IS NULL) = ("ai_accounts"."limited_until" IS NULL)),
	CONSTRAINT "ai_accounts_usage_windows" CHECK (("ai_accounts"."five_hour_utilization" IS NULL) = ("ai_accounts"."five_hour_resets_at" IS NULL) AND ("ai_accounts"."weekly_utilization" IS NULL) = ("ai_accounts"."weekly_resets_at" IS NULL)),
	CONSTRAINT "ai_accounts_pause_thresholds" CHECK (("ai_accounts"."five_hour_pause_threshold" IS NULL OR "ai_accounts"."five_hour_pause_threshold" BETWEEN 1 AND 100) AND ("ai_accounts"."weekly_pause_threshold" IS NULL OR "ai_accounts"."weekly_pause_threshold" BETWEEN 1 AND 100)),
	CONSTRAINT "ai_accounts_account_type" CHECK ("ai_accounts"."account_type" IN ('api_key', 'oauth', 'bedrock', 'vertex', 'endpoint')),
	CONSTRAINT "ai_accounts_cloud" CHECK (("ai_accounts"."account_type" IN ('bedrock', 'vertex')) = ("ai_accounts"."region" IS NOT NULL) AND ("ai_accounts"."account_type" = 'vertex') = ("ai_accounts"."project_id" IS NOT NULL)),
	CONSTRAINT "ai_accounts_credential_sealed" CHECK ("ai_accounts"."credential" LIKE 'aio1:%'),
	CONSTRAINT "ai_accounts_priority" CHECK ("ai_accounts"."priority" BETWEEN 1 AND 100),
	CONSTRAINT "ai_accounts_refresh_token_sealed" CHECK ("ai_accounts"."refresh_token" IS NULL OR "ai_accounts"."refresh_token" LIKE 'aio1:%'),
	CONSTRAINT "ai_accounts_extra_usage" CHECK (NOT "ai_accounts"."extra_usage" OR ("ai_accounts"."ai_provider" = 'Claude' AND "ai_accounts"."account_type" = 'oauth')),
	CONSTRAINT "ai_accounts_oauth_login" CHECK (("ai_accounts"."account_type" = 'oauth') = ("ai_accounts"."refresh_token" IS NOT NULL AND "ai_accounts"."token_expires_at" IS NOT NULL))
);

