	CONSTRAINT "batches_status" CHECK ("batches"."status" IN ('awaiting_approval', 'in_progress', 'finished')),
	CONSTRAINT "batches_issues" CHECK (cardinality("batches"."issues") BETWEEN 1 AND 50),
	CONSTRAINT "batches_started" CHECK (("batches"."status" = 'awaiting_approval') = ("batches"."started_at" IS NULL)),
	CONSTRAINT "batches_finished" CHECK (("batches"."status" = 'finished') = ("batches"."finished_at" IS NOT NULL AND "batches"."wrap_up" IS NOT NULL))
);

