	CONSTRAINT "connection_deliveries_delivered" CHECK (("connection_deliveries"."status" = 'delivered') = ("connection_deliveries"."delivered_at" IS NOT NULL)),
	CONSTRAINT "connection_deliveries_test" CHECK (NOT "connection_deliveries"."test" OR "connection_deliveries"."event_id" IS NULL),
	CONSTRAINT "connection_deliveries_attempts" CHECK ("connection_deliveries"."attempts" >= 0)
);

CREATE TABLE "connections" (
	"id" text PRIMARY KEY NOT NULL,
