	"digest_cursor" bigint DEFAULT 0 NOT NULL,
	"last_digest_at" timestamp with time zone,
	"created_at" timestamp with time zone NOT NULL,
	CONSTRAINT "connections_type" CHECK ("connections"."type" IN ('webhook', 'slack', 'email', 'ntfy', 'pushover', 'confluence', 'notion', 'google_sheets', 'google_docs', 'google_slides', 'google_drive', 'google_calendar')),
	CONSTRAINT "connections_detail_level" CHECK ("connections"."detail_level" IN ('links_only', 'titles_and_summaries')),
	CONSTRAINT "connections_status" CHECK ("connections"."status" IN ('ok', 'failing')),
	CONSTRAINT "connections_consecutive_failures" CHECK ("connections"."consecutive_failures" >= 0)
);

