	CONSTRAINT "direct_chat_messages_agent" CHECK (("direct_chat_messages"."chat" = 'terminal' AND "direct_chat_messages"."floor_id" IS NULL AND "direct_chat_messages"."agent_id" IS NULL) OR ("direct_chat_messages"."chat" = 'agent:' || "direct_chat_messages"."agent_id" AND "direct_chat_messages"."floor_id" IS NOT NULL))
