	"git_email" text,
	"template_id" text DEFAULT 'development' NOT NULL,
	"template_name" text DEFAULT 'Development' NOT NULL,
	"theme" text DEFAULT 'office' NOT NULL,
	"created_at" timestamp with time zone NOT NULL,
	"archived_at" timestamp with time zone,
	CONSTRAINT "floors_github_repository_id_unique" UNIQUE("github_repository_id"),
	CONSTRAINT "floors_id_slug" CHECK ("floors"."id" ~ '^[a-z0-9][a-z0-9-]*$'),
	CONSTRAINT "floors_merge_policy" CHECK ("floors"."merge_policy" IN ('send_to_me', 'auto_merge')),
	CONSTRAINT "floors_round_cap" CHECK ("floors"."round_cap" >= 1),
	CONSTRAINT "floors_token_caps" CHECK (("floors"."daily_token_cap" IS NULL OR "floors"."daily_token_cap" > 0) AND ("floors"."monthly_token_cap" IS NULL OR "floors"."monthly_token_cap" > 0)),
	CONSTRAINT "floors_concurrency_limit" CHECK ("floors"."concurrency_limit" IS NULL OR "floors"."concurrency_limit" >= 1),
	CONSTRAINT "floors_most_agents" CHECK ("floors"."most_agents" IS NULL OR "floors"."most_agents" >= 1),
	CONSTRAINT "floors_priority" CHECK ("floors"."priority" BETWEEN 0 AND 10),
	CONSTRAINT "floors_theme" CHECK ("floors"."theme" IN ('office', 'stockroom', 'studio', 'editorial', 'library', 'atelier', 'observatory', 'data-centre', 'device-lab')),
	CONSTRAINT "floors_fresh_start_threshold" CHECK ("floors"."fresh_start_threshold" BETWEEN 10 AND 100),
	CONSTRAINT "floors_git_identity" CHECK (("floors"."git_name" IS NULL) = ("floors"."git_email" IS NULL))
);

