CREATE TABLE "gateway_keys" (
	"id" text PRIMARY KEY NOT NULL,
	"kind" text NOT NULL,
	"name" text NOT NULL,
	"agent_id" text,
	"floor_id" text,
	"key_hash" text NOT NULL,
	"hint" text NOT NULL,
	"sealed_key" text,
