	CONSTRAINT "gateway_keys_owner" CHECK (("gateway_keys"."kind" = 'agent') = ("gateway_keys"."agent_id" IS NOT NULL AND "gateway_keys"."floor_id" IS NOT NULL AND "gateway_keys"."sealed_key" IS NOT NULL)),
	CONSTRAINT "gateway_keys_owner_tool" CHECK ("gateway_keys"."kind" = 'agent' OR ("gateway_keys"."agent_id" IS NULL AND "gateway_keys"."floor_id" IS NULL AND ("gateway_keys"."sealed_key" IS NULL) = ("gateway_keys"."kind" = 'owner_tool'))),
	CONSTRAINT "gateway_keys_sealed" CHECK ("gateway_keys"."sealed_key" IS NULL OR "gateway_keys"."sealed_key" LIKE 'aio1:%')
