CREATE TABLE "github_connections" (
	"id" text PRIMARY KEY NOT NULL,
	"kind" text NOT NULL,
	"name" text NOT NULL,
	"app_id" text,
	"private_key" text,
	"token" text,
	"read_only_token" text,
	"hint" text NOT NULL,
	"enabled" boolean DEFAULT true NOT NULL,
	"created_at" timestamp with time zone NOT NULL,
	CONSTRAINT "github_connections_kind" CHECK (("github_connections"."kind" = 'app' AND "github_connections"."app_id" IS NOT NULL AND "github_connections"."private_key" IS NOT NULL AND "github_connections"."token" IS NULL AND "github_connections"."read_only_token" IS NULL) OR ("github_connections"."kind" = 'access-token' AND "github_connections"."app_id" IS NULL AND "github_connections"."private_key" IS NULL AND "github_connections"."token" IS NOT NULL AND "github_connections"."read_only_token" IS NOT NULL)),
	CONSTRAINT "github_connections_private_key_sealed" CHECK ("github_connections"."private_key" IS NULL OR "github_connections"."private_key" LIKE 'aio1:%'),
	CONSTRAINT "github_connections_token_sealed" CHECK ("github_connections"."token" IS NULL OR "github_connections"."token" LIKE 'aio1:%'),
	CONSTRAINT "github_connections_read_only_token_sealed" CHECK ("github_connections"."read_only_token" IS NULL OR "github_connections"."read_only_token" LIKE 'aio1:%')
);

CREATE TABLE "google_sign_in" (
