);

CREATE TABLE "manager_chat_messages" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "manager_chat_messages_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"floor_id" text NOT NULL,
	"kind" text NOT NULL,
	"text" text NOT NULL,
	"command" jsonb,
	"reply_to" bigint,
	"agent_id" text,
	"model" text,
	"skill" jsonb,
	"skill_instructions" text,
	"grilling_session_id" bigint,
	"grilling_round" integer,
