	CONSTRAINT "manager_chat_messages_grilling_round" CHECK ("manager_chat_messages"."grilling_round" IS NULL OR ("manager_chat_messages"."grilling_session_id" IS NOT NULL AND "manager_chat_messages"."grilling_round" > 0)),
	CONSTRAINT "manager_chat_messages_reply_to" CHECK ("manager_chat_messages"."kind" IN ('report', 'summary') OR ("manager_chat_messages"."kind" = 'owner') = ("manager_chat_messages"."reply_to" IS NULL)),
	CONSTRAINT "manager_chat_messages_compaction" CHECK (("manager_chat_messages"."kind" = 'summary') = ("manager_chat_messages"."compaction" IS NOT NULL)),
	CONSTRAINT "manager_chat_messages_agent" CHECK (("manager_chat_messages"."kind" = 'owner') = ("manager_chat_messages"."agent_id" IS NULL)),
	CONSTRAINT "manager_chat_messages_command" CHECK (("manager_chat_messages"."kind" = 'command') = ("manager_chat_messages"."command" IS NOT NULL)),
	CONSTRAINT "manager_chat_messages_skill" CHECK ("manager_chat_messages"."skill" IS NULL OR "manager_chat_messages"."kind" IN ('owner', 'reply')),
	CONSTRAINT "manager_chat_messages_skill_instructions" CHECK (("manager_chat_messages"."skill" IS NULL) = ("manager_chat_messages"."skill_instructions" IS NULL))
);

