CREATE TABLE "office_settings" (
	"id" integer PRIMARY KEY DEFAULT 1 NOT NULL,
	"git_name" text,
	"git_email" text,
	"owner_login" text,
	"intake_interval_seconds" integer,
	"sandbox_concurrency_limit" integer,
	"gateway_store_bodies" boolean,
	"gateway_strategy" text,
	"gateway_session_window_minutes" integer,
	"gateway_retry_attempts" integer,
	"gateway_retry_delay_ms" integer,
	"gateway_retry_multiplier" double precision,
	"gateway_circuit_breaker_threshold" integer,
	"gateway_circuit_breaker_cooldown_seconds" integer,
	"gateway_five_hour_pacing" boolean,
	"gateway_weekly_pacing" boolean,
	"gateway_auto_refresh" boolean,
	"gateway_combos" boolean,
	"gateway_prompt_cache_ttl" text,
	"gateway_keep_alive" boolean,
	"gateway_keep_alive_idle_minutes" integer,
	"gateway_keep_alive_max_per_account_per_hour" integer,
	"gateway_outbound_proxy_url" text,
	"gateway_outbound_proxy_username" text,
	"gateway_outbound_proxy_password" text,
	"gateway_outbound_proxy_no_proxy" jsonb,
	"decision_model_enabled" boolean,
	"decision_model" text,
	"decision_model_summaries" boolean,
	"daily_token_cap" bigint,
	"monthly_token_cap" bigint,
	"retention_request_bodies_days" integer,
	"retention_request_metadata_days" integer,
	"retention_activity_days" integer,
	"retention_connection_deliveries_days" integer,
	"github_webhooks_enabled" boolean,
	"github_webhook_secret" text,
	"owner_profile" jsonb,
	"lobby_cast" jsonb,
	"floor_activities" jsonb,
	"seasonal_events" jsonb,
	"updated_at" timestamp with time zone NOT NULL,
	CONSTRAINT "office_settings_single_row" CHECK ("office_settings"."id" = 1),
	CONSTRAINT "office_settings_outbound_proxy" CHECK (("office_settings"."gateway_outbound_proxy_url" IS NOT NULL OR "office_settings"."gateway_outbound_proxy_username" IS NULL) AND ("office_settings"."gateway_outbound_proxy_username" IS NOT NULL OR "office_settings"."gateway_outbound_proxy_password" IS NULL) AND ("office_settings"."gateway_outbound_proxy_password" IS NULL OR "office_settings"."gateway_outbound_proxy_password" LIKE 'aio1:%')),
	CONSTRAINT "office_settings_sandbox_concurrency_limit" CHECK ("office_settings"."sandbox_concurrency_limit" IS NULL OR "office_settings"."sandbox_concurrency_limit" >= 1),
	CONSTRAINT "office_settings_intake_interval" CHECK ("office_settings"."intake_interval_seconds" IS NULL OR "office_settings"."intake_interval_seconds" >= 10),
	CONSTRAINT "office_settings_git_identity" CHECK (("office_settings"."git_name" IS NULL) = ("office_settings"."git_email" IS NULL)),
	CONSTRAINT "office_settings_gateway_strategy" CHECK ("office_settings"."gateway_strategy" IS NULL OR "office_settings"."gateway_strategy" IN ('session', 'session_affinity', 'drain_soonest', 'drain_soonest_strict', 'least_used')),
	CONSTRAINT "office_settings_gateway_session_window" CHECK ("office_settings"."gateway_session_window_minutes" IS NULL OR "office_settings"."gateway_session_window_minutes" BETWEEN 1 AND 10080),
	CONSTRAINT "office_settings_gateway_retries" CHECK (("office_settings"."gateway_retry_attempts" IS NULL OR "office_settings"."gateway_retry_attempts" BETWEEN 1 AND 10) AND ("office_settings"."gateway_retry_delay_ms" IS NULL OR "office_settings"."gateway_retry_delay_ms" BETWEEN 0 AND 60000) AND ("office_settings"."gateway_retry_multiplier" IS NULL OR "office_settings"."gateway_retry_multiplier" BETWEEN 1 AND 10)),
	CONSTRAINT "office_settings_gateway_prompt_cache_ttl" CHECK ("office_settings"."gateway_prompt_cache_ttl" IS NULL OR "office_settings"."gateway_prompt_cache_ttl" IN ('5m', '1h')),
	CONSTRAINT "office_settings_gateway_keep_alive" CHECK (("office_settings"."gateway_keep_alive_idle_minutes" IS NULL OR "office_settings"."gateway_keep_alive_idle_minutes" BETWEEN 5 AND 480) AND ("office_settings"."gateway_keep_alive_max_per_account_per_hour" IS NULL OR "office_settings"."gateway_keep_alive_max_per_account_per_hour" BETWEEN 1 AND 600)),
	CONSTRAINT "office_settings_token_caps" CHECK (("office_settings"."daily_token_cap" IS NULL OR "office_settings"."daily_token_cap" > 0) AND ("office_settings"."monthly_token_cap" IS NULL OR "office_settings"."monthly_token_cap" > 0)),
	CONSTRAINT "office_settings_retention" CHECK (("office_settings"."retention_request_bodies_days" IS NULL OR "office_settings"."retention_request_bodies_days" BETWEEN 0 AND 3650) AND ("office_settings"."retention_request_metadata_days" IS NULL OR "office_settings"."retention_request_metadata_days" BETWEEN 32 AND 3650) AND ("office_settings"."retention_activity_days" IS NULL OR "office_settings"."retention_activity_days" BETWEEN 30 AND 3650) AND ("office_settings"."retention_connection_deliveries_days" IS NULL OR "office_settings"."retention_connection_deliveries_days" BETWEEN 1 AND 3650)),
	CONSTRAINT "office_settings_github_webhook_secret_sealed" CHECK ("office_settings"."github_webhook_secret" IS NULL OR "office_settings"."github_webhook_secret" LIKE 'aio1:%'),
	CONSTRAINT "office_settings_github_webhooks_secret" CHECK ("office_settings"."github_webhooks_enabled" IS NOT TRUE OR "office_settings"."github_webhook_secret" IS NOT NULL),
	CONSTRAINT "office_settings_gateway_circuit_breaker" CHECK (("office_settings"."gateway_circuit_breaker_threshold" IS NULL OR "office_settings"."gateway_circuit_breaker_threshold" BETWEEN 1 AND 100) AND ("office_settings"."gateway_circuit_breaker_cooldown_seconds" IS NULL OR "office_settings"."gateway_circuit_breaker_cooldown_seconds" BETWEEN 1 AND 3600))
);

