);

CREATE TABLE "review_verdicts" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "review_verdicts_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"floor_id" text NOT NULL,
	"issue" integer NOT NULL,
	"pull_request" integer NOT NULL,
	"round" integer NOT NULL,
	"agent_id" text NOT NULL,
	"head_sha" text NOT NULL,
	"verdict" text NOT NULL,
	"summary" text NOT NULL,
	"comments" jsonb DEFAULT '[]' NOT NULL,
	"review_url" text NOT NULL,
	"created_at" timestamp with time zone NOT NULL,
	CONSTRAINT "review_verdicts_verdict" CHECK ("review_verdicts"."verdict" IN ('approve', 'changes_requested')),
	CONSTRAINT "review_verdicts_numbers" CHECK ("review_verdicts"."issue" > 0 AND "review_verdicts"."pull_request" > 0 AND "review_verdicts"."round" > 0)
);

CREATE TABLE "role_memory" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "role_memory_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"floor_id" text NOT NULL,
	"role" text NOT NULL,
	"text" text NOT NULL,
	"status" text DEFAULT 'proposed' NOT NULL,
	"issue" integer NOT NULL,
	"agent_id" text NOT NULL,
	"created_at" timestamp with time zone NOT NULL,
	"decided_by" text,
	"decided_at" timestamp with time zone,
	"reason" text,
	CONSTRAINT "role_memory_text" CHECK (length("role_memory"."text") BETWEEN 1 AND 300 AND position(E'\n' in "role_memory"."text") = 0),
	CONSTRAINT "role_memory_status" CHECK ("role_memory"."status" IN ('proposed', 'recommended', 'accepted', 'rejected', 'removed')),
	CONSTRAINT "role_memory_issue" CHECK ("role_memory"."issue" > 0),
	CONSTRAINT "role_memory_decided" CHECK (("role_memory"."status" = 'proposed') = ("role_memory"."decided_by" IS NULL) AND ("role_memory"."decided_by" IS NULL) = ("role_memory"."decided_at" IS NULL) AND ("role_memory"."decided_by" IS NULL OR "role_memory"."decided_by" IN ('manager', 'owner')) AND ("role_memory"."status" <> 'recommended' OR "role_memory"."decided_by" = 'manager') AND ("role_memory"."status" NOT IN ('accepted', 'removed') OR "role_memory"."decided_by" = 'owner')),
	CONSTRAINT "role_memory_reason" CHECK ("role_memory"."reason" IS NULL OR length("role_memory"."reason") <= 300)
);

CREATE TABLE "roles" (
	"id" text PRIMARY KEY NOT NULL,
	"name" text NOT NULL,
	"stage" text NOT NULL,
	"description" text NOT NULL,
	"instructions" text NOT NULL,
	"skills" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"desk_dressing" text NOT NULL,
	"ai_provider" text,
	"model" text,
	"floor_id" text,
	"created_at" timestamp with time zone NOT NULL,
	"updated_at" timestamp with time zone NOT NULL,
	CONSTRAINT "roles_one_off_stage" CHECK ("roles"."floor_id" IS NULL OR "roles"."stage" = 'work'),
	CONSTRAINT "roles_id" CHECK ("roles"."id" ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length("roles"."id") <= 40 AND "roles"."id" <> 'manager'),
	CONSTRAINT "roles_stage" CHECK ("roles"."stage" IN ('work', 'review', 'qa', 'docs')),
	CONSTRAINT "roles_desk_dressing" CHECK ("roles"."desk_dressing" IN ('monitor', 'dual-monitors', 'printouts', 'test-devices', 'books', 'notebooks', 'product-samples')),
	CONSTRAINT "roles_model" CHECK ("roles"."model" IS NULL OR "roles"."ai_provider" IS NOT NULL)
);

