CREATE TABLE "skills" (
	"id" text PRIMARY KEY NOT NULL,
	"name" text NOT NULL,
	"description" text NOT NULL,
	"source" text NOT NULL,
	"git_url" text,
	"git_ref" text,
	"git_commit" text,
	"git_path" text,
	"files" jsonb NOT NULL,
	"digest" text NOT NULL,
	"enabled" boolean DEFAULT false NOT NULL,
	"reviewed_at" timestamp with time zone,
	"created_at" timestamp with time zone NOT NULL,
	"updated_at" timestamp with time zone NOT NULL,
	CONSTRAINT "skills_name_unique" UNIQUE("name"),
	CONSTRAINT "skills_source" CHECK ("skills"."source" IN ('upload', 'git', 'editor', 'template')),
	CONSTRAINT "skills_enabled_reviewed" CHECK (NOT "skills"."enabled" OR "skills"."reviewed_at" IS NOT NULL),
	CONSTRAINT "skills_git_origin" CHECK (("skills"."source" = 'git') = ("skills"."git_url" IS NOT NULL AND "skills"."git_commit" IS NOT NULL AND "skills"."git_path" IS NOT NULL)),
	CONSTRAINT "skills_digest" CHECK ("skills"."digest" ~ '^[0-9a-f]{64}$')
);

